 $('project-storage').innerHTML=`<details ${archives.length?'open':''}><summary>${archives.length?archives.length+' earlier saved project'+(archives.length===1?'':'s')+' available':'Your work stays in this browser'}</summary><p>Choices save on this device and browser only. To move work to another device or share it with your adviser, export the full project. Photos in an unfinished form are kept only until you reload or close this page.</p>${archives.length?'<p>This model has a different evidence revision. Earlier decisions have been preserved below; they have not been applied to this model. Download the original project for a review of changed evidence before continuing.</p>':''}${archives.map((a,i)=>`<details class="saved-archive"><summary>Evidence ${esc(a.revision)} · ${a.project?a.project.events.length+' changes · '+a.project.observations.length+' evidence records':'Unreadable project · original available'}</summary>${a.project?`<p>Recorded history only; quantities have not been recalculated.</p><ul>${a.project.events.map(e=>`<li>${esc(e.at)} — ${esc(e.label)}</li>`).join('')}</ul><ul>${a.project.observations.map(o=>`<li>${esc(o.observer)} · ${esc(roleLabels[o.role]||o.role)}: ${esc(o.note)}</li>`).join('')}</ul>`:''}<button data-download-archive="${i}">Download original saved project</button></details>`).join('')}</details>`;
 document.querySelectorAll('[data-download-archive]').forEach(b=>b.onclick=()=>{try{download('3-broom-road-saved-'+archives[+b.dataset.downloadArchive].revision+'.json','{"project":'+S.archiveRaw(archives[+b.dataset.downloadArchive].key)+'}','application/json');}catch(e){message(e.message);}});
