 $('journey-context').innerHTML=`<div class="context-card"><span class="eyebrow">3 BROOM ROAD / REMOTE PROPOSAL</span>${step!==3&&step!==2?photo(im):''}<h3>${esc(b.selected.title)}</h3><p>${b.selected.changedRooms} rooms with indicated changes · ${b.selected.unknownRooms} room outputs unknown</p><div class="progress-strip"><span>Remote model</span><span>Evidence ${shown.observations.length}</span><span>Design review open</span></div>${b.selected.blocked?'<p class="warning">Selected cylinder space conflicts with your household preference.</p>':''}${b.selected.geometryPending?'<p class="warning">Measurements received. Geometry and dependent sizing need review.</p>':''}</div>`;
 const tasks=J.tasks(D,project),t=tasks[0];$('journey-next-check').innerHTML=`<div class="next-check"><span class="eyebrow">${role==='customer'?'WHAT WOULD HELP NEXT':'SURVEY BRIEF'}</span><h3>${esc(t.title)}</h3><p>${esc(t.why)}</p><button data-open-task="${t.id}">See this check →</button>${role!=='customer'?'<p class="subtle">Shared project with the technical workbench. Site evidence updates supported thermal choices and emitter ratings. Geometry revisions still require a rebuilt release.</p>':''}</div>`;
