$('house-front').onclick=()=>view.view('front');$('house-rear').onclick=()=>view.view('rear');$('journey-summary').onclick=()=>download('3-broom-road-your-plan.html',summary(),'text/html');
$('journey-export').onclick=()=>download('3-broom-road-installation.json',JSON.stringify({project,sourceHashes:D.sourceHashes,packages:J.packages(D,project),designApproved:false},null,2),'application/json');
$('journey-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const incoming=J.validate(JSON.parse(await file.text()).project,D);commit(J.importProject(project,D,incoming));}catch(error){message(error.message);}e.target.value='';};
window.addEventListener('beforeunload',e=>{const forms=new Set([...evidenceForms.values(),...document.querySelectorAll('form[data-evidence-key]')]);if([...forms].some(f=>[...f.elements].some(el=>el.type==='file'?el.files.length:el.type==='checkbox'?el.checked!==el.defaultChecked:el.tagName==='INPUT'||el.tagName==='TEXTAREA'?el.value!==el.defaultValue:false))){e.preventDefault();e.returnValue='';}});
window.addEventListener('storage',e=>{if(e.key===S.key)message('This project changed in another tab. Reload before making further edits.');});
window.__BROOM_INSTALLATION__={go,get project(){return project;},get brief(){return J.brief(D,project);},get step(){return step;},get cursor(){return cursor;},view,summary};
